import Foundation

/// Production scope construction and receipt checks. SHA-256 expectations are
/// fixed vectors from Python hashlib over the written ASCII manifest, never
/// digests generated by the native implementation under test.
@main private enum AtlasVisibleSearchWireTests {
    private static let emptyDigest = "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
    private static let pairDigest = "c221d3ff13ebd9df30c4043477954a7526d34ee24a0a611ffe00792578b03070"

    private static func check(_ value: Bool) { precondition(value) }

    private static func reject(_ message: String, _ operation: () throws -> Void) {
        do { try operation(); preconditionFailure(message) } catch { }
    }
    private static func rejectReceipt(_ message: String, _ operation: () throws -> Void) {
        do { try operation(); preconditionFailure(message) }
        catch AtlasSearchError.invalidResponse { }
        catch { preconditionFailure("Receipt failure changed error type: \(error)") }
    }

    static func main() throws {
        try nonVisibleScopesRejectRegionReceipts()
#if canImport(CryptoKit)
        try canonicalMembershipAndFixedDigests()
        try rawNamesRemainDistinctAndDelimiterSafe()
        try emptyScopeCannotMeanWorkspace()
        try limitsRejectUnboundedOrInvalidManifests()
        try exactMetadataEchoesAreRequired()
        try missingMembershipCannotClaimCompleteCoverage()
        print("Visible scope canonical identities, exact raw membership, limits, metadata echoes and missing-membership coverage checks passed.")
#else
        // This is an unavailable capability, not a substitute SHA result or a
        // successful empty/workspace query. Portable nonvisible tests continue
        // to compile without adding a crypto package to the host fixture.
        for paths: [[UInt8]] in [[], [Array("a.rs".utf8)]] {
            do {
                _ = try AtlasSearchPathScope(visiblePaths: paths)
                preconditionFailure("Visible scope silently succeeded without its digest provider")
            } catch AtlasSearchError.unavailable { }
        }
        print("CryptoKit unavailable: visible scope correctly reports unavailable. Positive visible factory/receipt checks were not executed on this host.")
#endif
    }

    private static func nonVisibleScopesRejectRegionReceipts() throws {
        let workspace = AtlasSearchPathScope.workspace
        try workspace.validateEcho(kind: nil, path: nil, hex: nil)
        check(try workspace.validateRegionCoverage(catalogued: nil, missing: nil,
            eligible: 0, searchCatalogFiles: 0, allFileTypes: true, complete: true) == 0)
        let file = try AtlasSearchPathScope(kind: .file, path: "a.rs")
        try file.validateEcho(kind: "file", path: "a.rs", hex: "612e7273")
        for scope in [workspace, file] {
            rejectReceipt("Nonvisible scope accepted a visible digest") {
                try scope.validateEcho(kind: scope.kind.rawValue, path: scope.path, hex: scope.pathHex,
                    regionSHA256: emptyDigest)
            }
            rejectReceipt("Nonvisible scope accepted visible counts") {
                try scope.validateEcho(kind: scope.kind.rawValue, path: scope.path, hex: scope.pathHex,
                    regionFiles: "0", regionPathBytes: "0")
            }
            rejectReceipt("Nonvisible scope inherited visible membership coverage") {
                _ = try scope.validateRegionCoverage(catalogued: "0", missing: "0",
                    eligible: 0, searchCatalogFiles: 0, allFileTypes: true, complete: true)
            }
        }
    }

#if canImport(CryptoKit)
    private static func canonicalMembershipAndFixedDigests() throws {
        let a = Array("a.rs".utf8), z = Array("z.rs".utf8)
        let scope = try AtlasSearchPathScope(visiblePaths: [z, a, z, a])
        let ordered = try AtlasSearchPathScope(visiblePaths: [a, z])
        precondition(scope == ordered && scope.kind == .visible && scope.isVisible && !scope.isWorkspace)
        precondition(scope.visibleCount == 2 && scope.path == "612e7273,7a2e7273" && scope.pathHex.isEmpty)
        precondition(scope.visibleIdentity == pairDigest && ordered.visibleIdentity == pairDigest)
        precondition(scope.admitsRawPath(a) && scope.admitsRawPath(z))
        for outside in ["A.rs", "a.rs.bak", "a.rs/child", "a", "other.rs"] {
            precondition(!scope.admitsRawPath(Array(outside.utf8)))
        }
        precondition(!scope.admitsRawPath([]))
        scope.withCString { kind, path in
            precondition(kind == 3 && path != nil && String(cString: path!) == "612e7273,7a2e7273")
        }
        let single = try AtlasSearchPathScope(visiblePaths: [Array("a".utf8)])
        precondition(single.path == "61"
            && single.visibleIdentity == "d029fa3a95e174a19934857f535eb9427d967218a36ea014b70ad704bc6c8d1c")
        let input = try AtlasSearchInput(root: "/repo", query: "needle", pathScope: scope)
        precondition(!input.isWorkspaceScope && input.pathScope == scope)
        do { try input.requireLegacyScope(); preconditionFailure("Legacy query widened visible membership") }
        catch AtlasSearchError.invalidPathScope { }
    }

    private static func rawNamesRemainDistinctAndDelimiterSafe() throws {
        let composed = Array("café.rs".utf8), decomposed = Array("cafe\u{301}.rs".utf8), invalidUTF8: [UInt8] = [255, 46, 114, 115]
        precondition(String(decoding: composed, as: UTF8.self) == String(decoding: decomposed, as: UTF8.self))
        let scope = try AtlasSearchPathScope(visiblePaths: [invalidUTF8, composed, decomposed])
        precondition(scope.visibleCount == 3
            && scope.path == "63616665cc812e7273,636166c3a92e7273,ff2e7273"
            && scope.visibleIdentity == "5b4e3612c03c555a3512fa737c37c6888753c8dc8f00c2d30408d25289bb6e36")
        precondition(scope.admitsRawPath(composed) && scope.admitsRawPath(decomposed) && scope.admitsRawPath(invalidUTF8))
        let first = try AtlasSearchPathScope(visiblePaths: [composed])
        let second = try AtlasSearchPathScope(visiblePaths: [decomposed])
        precondition(first != second && !first.admitsRawPath(decomposed) && !second.admitsRawPath(composed))
        precondition(first.visibleIdentity == "cbf99e687b3aad8098e6bbafcdf1fe8caf97127d630ef42164ded41a92728fac"
            && second.visibleIdentity == "46b5e8c6cd8542dd2b81f3e4a3e06c0fb153e5bba02291684831b82a63651822")
        let punctuation = [Array("src/line\nname.rs".utf8), Array("a\\b.rs".utf8), Array("src/comma,name.rs".utf8)]
        let escaped = try AtlasSearchPathScope(visiblePaths: punctuation)
        precondition(escaped.path == "615c622e7273,7372632f636f6d6d612c6e616d652e7273,7372632f6c696e650a6e616d652e7273")
        precondition(escaped.visibleIdentity == "3554261498cc322a7f57ecc2ba7be55b414d9d8d99c1c641ed6cde01c9e1b093")
        precondition(punctuation.allSatisfy { escaped.admitsRawPath($0) }
            && !escaped.admitsRawPath(Array("a/b.rs".utf8)))
    }

    private static func emptyScopeCannotMeanWorkspace() throws {
        let empty = try AtlasSearchPathScope(visiblePaths: [])
        precondition(empty.isVisible && !empty.isWorkspace && empty.visibleCount == 0
            && empty.path.isEmpty && empty.visibleIdentity == emptyDigest)
        precondition(empty != .workspace && !empty.admitsRawPath([]) && !empty.admitsRawPath(Array("any.rs".utf8)))
        empty.withCString { kind, path in precondition(kind == 3 && path != nil && String(cString: path!).isEmpty) }
        try empty.validateEcho(kind: "visible", path: "", hex: "", regionSHA256: emptyDigest,
            regionFiles: "0", regionPathBytes: "0")
        check(try empty.validateRegionCoverage(catalogued: "0", missing: "0",
            eligible: 0, searchCatalogFiles: 4096, allFileTypes: true, complete: true) == 0)
        rejectReceipt("Empty visible scope inherited an omitted workspace echo") {
            try empty.validateEcho(kind: nil, path: nil, hex: nil)
        }
    }

    private static func limitsRejectUnboundedOrInvalidManifests() throws {
        let invalid: [[UInt8]] = [[], [0], Array("/a".utf8), Array(".".utf8), Array("..".utf8),
            Array("a/".utf8), Array("a//b".utf8), Array("a/./b".utf8), Array("a/../b".utf8),
            Array("a\0b".utf8), Array(repeating: 97, count: 4097)]
        for path in invalid {
            reject("Invalid raw path was admitted") { _ = try AtlasSearchPathScope(visiblePaths: [path]) }
        }
        reject("Unqualified visible string bypassed manifest construction") {
            _ = try AtlasSearchPathScope(kind: .visible, path: "612e7273")
        }
        let longest = Array(repeating: UInt8(97), count: 4096)
        check(try AtlasSearchPathScope(visiblePaths: [longest]).admitsRawPath(longest))
        reject("File-count bound was applied only after deduplication") {
            _ = try AtlasSearchPathScope(visiblePaths: Array(repeating: Array("a".utf8), count: 20_001))
        }
        let many = (0..<20_000).map { Array(String(format: "f%05d.rs", $0).utf8) }
        let largestCount = try AtlasSearchPathScope(visiblePaths: many)
        precondition(largestCount.visibleCount == 20_000 && largestCount.admitsRawPath(many[19_999]))

        // 128*4095 + 64 raw bytes and 128 separators produce exactly 1 MiB
        // of canonical hex. One additional raw byte must refuse the whole set.
        var exact = (0..<128).map { index in
            Array((String(format: "%03d", index) + String(repeating: "a", count: 4092)).utf8)
        }
        exact.append(Array(repeating: 122, count: 64))
        let full = try AtlasSearchPathScope(visiblePaths: exact)
        precondition(full.path.utf8.count == 1_048_576 && full.visibleCount == 129)
        exact[128].append(122)
        reject("Oversized encoded manifest was partially admitted") { _ = try AtlasSearchPathScope(visiblePaths: exact) }
        reject("Repeated long names bypassed input byte admission") {
            _ = try AtlasSearchPathScope(visiblePaths: Array(repeating: longest, count: 129))
        }
    }

    private static func exactMetadataEchoesAreRequired() throws {
        let scope = try AtlasSearchPathScope(visiblePaths: [Array("a.rs".utf8), Array("z.rs".utf8)])
        let expected: [String?] = ["visible", "", "", pairDigest, "2", "8"]
        func admit(_ fields: [String?]) throws {
            try scope.validateEcho(kind: fields[0], path: fields[1], hex: fields[2],
                regionSHA256: fields[3], regionFiles: fields[4], regionPathBytes: fields[5])
        }
        try admit(expected)
        for index in expected.indices {
            var missing = expected; missing[index] = nil
            rejectReceipt("Missing visible receipt field \(index) was accepted") { try admit(missing) }
        }
        let mutations: [(Int, String)] = [(0, "workspace"), (0, "file"), (1, scope.path), (2, "61"),
            (3, emptyDigest), (3, pairDigest.uppercased()), (4, "1"), (4, "02"), (5, "7"), (5, "08")]
        for (index, value) in mutations {
            var wrong = expected; wrong[index] = value
            rejectReceipt("Wrong visible receipt field \(index) was accepted") { try admit(wrong) }
        }
    }

    private static func missingMembershipCannotClaimCompleteCoverage() throws {
        let scope = try AtlasSearchPathScope(visiblePaths: [Array("a.rs".utf8), Array("z.rs".utf8)])
        check(try scope.validateRegionCoverage(catalogued: "2", missing: "0", eligible: 2,
            searchCatalogFiles: 4096, allFileTypes: true, complete: true) == 0)
        check(try scope.validateRegionCoverage(catalogued: "1", missing: "1", eligible: 1,
            searchCatalogFiles: 1, allFileTypes: true, complete: false) == 1)
        check(try scope.validateRegionCoverage(catalogued: "0", missing: "2", eligible: 0,
            searchCatalogFiles: 0, allFileTypes: true, complete: false) == 2)
        check(try scope.validateRegionCoverage(catalogued: "2", missing: "0", eligible: 1,
            searchCatalogFiles: 2, allFileTypes: false, complete: true) == 0)
        typealias Counts = (known: String?, missing: String?, eligible: Int, catalog: Int, all: Bool, complete: Bool)
        let invalid: [Counts] = [
            ("1", "1", 1, 1, true, true), // Missing membership cannot be a complete negative.
            (nil, "0", 2, 2, true, false), ("2", nil, 2, 2, true, false),
            ("3", "0", 2, 3, false, false), ("0", "3", 0, 0, true, false),
            ("1", "0", 1, 1, true, false), ("2", "1", 2, 2, true, false),
            ("2", "0", 2, 1, true, false), ("1", "1", 2, 2, false, false),
            ("2", "0", 1, 2, true, false), ("2", "0", -1, 2, false, false),
            ("2", "0", 2, -1, true, false), ("02", "0", 2, 2, true, false),
            ("2", "00", 2, 2, true, false), ("-1", "3", 0, 2, false, false),
            ("18446744073709551616", "0", 0, 2, false, false)
        ]
        for row in invalid {
            rejectReceipt("Incoherent visible membership coverage was accepted") {
                _ = try scope.validateRegionCoverage(catalogued: row.known, missing: row.missing,
                    eligible: row.eligible, searchCatalogFiles: row.catalog,
                    allFileTypes: row.all, complete: row.complete)
            }
        }
    }
#endif
}
